head.script:
scwin.___isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    if (myNav.indexOf('msie') != -1) {
        return parseInt(myNav.split('msie')[1]);
    } else if (myNav.substr(myNav.indexOf('rv') + 3, 2) == "11" || myNav.substr(myNav.indexOf('rv') + 2, 2) == "16") {
        return true;
    } else {
        return false;
    }
}
scwin.__isCheck = function() {
    return scwin.___isIE() ? WebSquare.wUnit.getJq("#SearchBox1___input").hasClass("w2searchbox_reset_remove") : true;
}
scwin.setSimulate = function() {
    WebSquare.wUnit.getJq('#SearchBox1___input').simulate('key-sequence', {
        sequence: 'search'
    });
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('SearchBox1___input').focus()");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#SearchBox1___reset').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Testcase test for IE Browser.
    //Function unitTest
    //Created By: Sang.do
    //Created By: 14-Mar-2018
    window.addEventListener("keydown", function(e) {
        console.log(e);
    })
}
